/**
 * Items that are not simply "the item of a block" (spec 2.2), plus the three wooden blocks that double as fuel.
 * Every other block gets its item generated by the registry from BLOCK_SPECS.
 *
 * `category` is only a grouping for the UI. Whether something burns is decided by `fuel` (registry `fuelOf`),
 * never by the category: sticks are a resource and logs are blocks, yet all of them are fuel.
 */
import { WELL_FED_DURATION_S } from '../core/constants';
import type { FoodSpec, FuelSpec, ItemSpec, ToolKind } from '../core/types';
import { BLOCK_SPECS } from './blocks';
import { areaItems } from './area';
import { EMBER_ITEMS } from './emberbound';
import { BREW_ITEMS } from './itemsBrew';
import { DISTILL_ITEMS } from './itemsDistill';
import { GROUND_ITEMS } from './itemsGround';
import { MAGIC_ITEMS } from './itemsMagic';
import { WORKSHOP_ITEMS } from './itemsWorkshop';
import { GLASS_ITEMS } from './itemsGlass';
import { SUGAR_ITEMS } from './itemsSugar';
import { HAND_ITEMS } from './itemsHand';
import { VEHICLE_ITEMS } from './itemsVehicle';

const fuel = (energyKJ: number, burnS: number, flameTempC: number): FuelSpec => ({ energyJ: energyKJ * 1000, burnS, flameTempC });

/** The item of a block that can also go in a firebox; name, text and age are taken from the block. */
function burnableBlock(key: string, spec: FuelSpec): ItemSpec {
  const placed = BLOCK_SPECS.find((b) => b.key === key);
  if (!placed) throw new Error(`content: burnable block "${key}" does not exist`);
  return { key, name: placed.name, desc: placed.desc, category: 'block', age: placed.age ?? 0, fuel: spec };
}

interface ToolSet {
  material: string;
  name: string;
  tier: number;
  speed: number;
  durability: number;
  age: number;
  /** What this tier of pickaxe, axe and shovel is for, in that order. */
  desc: [string, string, string];
}

const TOOL_KINDS: Array<[ToolKind, string]> = [['pickaxe', 'Pickaxe'], ['axe', 'Axe'], ['shovel', 'Shovel']];

/** A hoe tills grass or dirt into farmland (1 durability per use). It is no mining tool: speed 1, and it counts as bare hands. */
const hoe = (material: string, name: string, tier: number, durability: number, age: number, desc: string): ItemSpec => ({
  key: `${material}_hoe`, name: `${name} Hoe`, desc, category: 'tool', age, tool: { kind: 'hoe', tier, speed: 1, durability },
});

const food = (hunger: number): FoodSpec => ({ hunger });

function toolSet(set: ToolSet): ItemSpec[] {
  return TOOL_KINDS.map(([kind, label], i) => ({
    key: `${set.material}_${kind}`,
    name: `${set.name} ${label}`,
    desc: set.desc[i],
    category: 'tool',
    age: set.age,
    tool: { kind, tier: set.tier, speed: set.speed, durability: set.durability },
  }));
}

